.user-menu {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.user-pill {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--surface-subtle);
  padding: 0.32rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border);
}

/* --- LAYOUT & EN-TÊTE --- */
.wrap {
  max-width: 1240px;
  margin: 0 auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.page-header h1 {
  margin: 0;
  font-size: 1.375rem;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--text);
}

.page-header p {
  margin: 0.2rem 0 0;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.toast-banner {
  background: var(--primary-soft);
  border: 1px solid var(--primary-border);
  color: var(--primary-hover);
  padding: 0.65rem 1rem;
  border-radius: 10px;
  font-size: 0.86rem;
  font-weight: 500;
}

.layout {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 1.25rem;
  align-items: stretch;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border);
}

.card-head h2 {
  margin: 0;
  font-size: 1.02rem;
  font-weight: 600;
  color: var(--text);
}

.card-subtitle {
  margin: 0.15rem 0 0;
  font-size: 0.82rem;
  color: var(--muted);
}

.muted-count {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
  background: var(--surface-subtle);
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.badge-info {
  background: var(--surface-subtle);
  color: var(--text);
  border: 1px solid var(--border);
  font-weight: 600;
  font-size: 0.8rem;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
}

.hint-text {
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 500;
}

/* --- CALENDRIER --- */
.cal-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
}

table.cal {
  width: 100%;
  height: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border);
}

table.cal th {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  background: var(--surface-subtle);
  padding: 0.55rem 0.25rem;
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
}

table.cal td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  height: 88px;
  vertical-align: top;
  padding: 0.35rem;
  background: var(--surface);
  transition: background-color 0.12s ease;
}

table.cal td.blank {
  background: #f8fafc;
}

table.cal td.active-range {
  background: #fffaf5;
  box-shadow: inset 0 2px 0 var(--primary);
}

.dnum {
  font-size: 0.78rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  color: var(--text-secondary);
}

.mark {
  width: 100%;
  border: none;
  border-radius: 4px;
  font-size: 0.71rem;
  font-weight: 600;
  padding: 0.22rem 0.4rem;
  margin-bottom: 0.2rem;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: opacity 0.12s ease, transform 0.12s ease;
}

.mark:hover {
  opacity: 0.9;
}

/* --- PANNEAU ACTIONS & ÉTAPES --- */
.tabs {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-bottom: 1rem;
}

.tab-btn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.6rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s ease;
}

.tab-btn:hover {
  background: var(--surface-subtle);
}

.tab-btn.selected {
  border-color: var(--border-strong);
  background: var(--surface-subtle);
  font-weight: 600;
}

.tab-stat {
  font-size: 0.78rem;
  color: var(--muted);
  font-weight: 600;
}

.detail {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
}

.detail-header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.65rem;
  margin-bottom: 0.45rem;
}
.detail-header h3 {
  margin: 0;
  width: 100%;
  font-size: 1.15rem;
  line-height: 1.28;
  font-weight: 700;
  letter-spacing: -0.01em;
  word-break: break-word;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
}

.detail h3 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
}

.meta {
  color: var(--muted);
  font-size: 0.82rem;
  margin: 0.25rem 0 0.9rem;
}

.step {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 8px;
  padding: 0.65rem 0.8rem;
  margin-bottom: 0.55rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  transition: border-color 0.15s ease;
}

.step:hover {
  border-color: var(--border-strong);
}

.step-left {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
}

.step-check {
  width: 17px;
  height: 17px;
  margin-top: 0.22rem;
  accent-color: #16a34a;
  cursor: pointer;
  flex-shrink: 0;
}

.step-date { font-size: 0.75rem; font-weight: 600; }
.step-text { margin: 0.12rem 0; font-size: 0.87rem; font-weight: 500; color: var(--text); }
.step-text.is-done { text-decoration: line-through; color: var(--muted); }
.step-who { font-size: 0.77rem; color: var(--muted); }

.st {
  border: none;
  border-radius: 999px;
  padding: 0.24rem 0.65rem;
  font-size: 0.73rem;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
}

.st-todo { background: var(--surface-subtle); color: var(--text-secondary); border: 1px solid var(--border); }
.st-doing { background: #ffedd5; color: #c2410c; }
.st-done { background: #dcfce7; color: #15803d; }

.empty-state {
  text-align: center;
  padding: 1.75rem 1rem;
  color: var(--muted);
  font-size: 0.88rem;
  background: var(--surface-subtle);
  border-radius: 10px;
}

/* --- FORMULAIRE --- */
.project-form { display: flex; flex-direction: column; gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0.85rem; }

.field {
  display: flex;
  flex-direction: column;
  gap: 0.32rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.field input, .field select {
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 0.52rem 0.7rem;
  font-size: 0.88rem;
  font-family: inherit;
  color: var(--text);
  background: var(--surface);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field input:focus, .field select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(234, 88, 12, 0.12);
}

.steps-builder {
  border: 1px solid var(--border);
  background: var(--surface-subtle);
  border-radius: 10px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.steps-builder-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.steps-builder-head strong {
  font-size: 0.9rem;
  color: var(--text);
  display: block;
}
